"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "./app-link";
import { CallNoteControl } from "./object-workspace";
import { ViewportModal } from "./viewport-modal";
import { useTopologyExtensions } from "../lib/topology-client";
import type {
  InfrastructureConnection,
  InfrastructureNode,
  InfrastructureNodeType,
  InfrastructurePortfolio,
  InfrastructureProductInstallation,
  ReleaseInfrastructureNode,
} from "../lib/topology-model";

const nodeTypeLabels: Record<InfrastructureNodeType, string> = {
  ups: "UPS / power",
  network_switch: "Network switch",
  chassis: "Chassis",
  blade: "Blade",
  physical_server: "Physical server",
  storage_array: "Storage array",
  logical_drive: "Logical / local drive",
  virtual_machine: "Virtual machine",
  appliance: "Appliance",
  other: "Other",
};

const roles = ["operating_system", "hypervisor", "application", "middleware", "database", "runtime", "firmware", "agent", "other"] as const;
const readable = (value: string) => value.replaceAll("_", " ").replace(/\b\w/g, (letter) => letter.toUpperCase());
const valueOrUnknown = (value: unknown) => value === null || value === undefined || value === "" ? "Not recorded" : String(value);

const emptyNode = {
  id: "", nodeType: "physical_server" as InfrastructureNodeType, code: "", name: "", manufacturerOrganizationId: "", hardwareProductId: "", assetTag: "", serialNumber: "", lifecycleStatus: "active", description: "",
};
const emptyState = {
  id: "", infrastructureNodeId: "", parentStateId: "", lifecycleStatus: "active", operatingState: "unknown", confidence: "assessed", cpuCores: "", memoryGb: "", storageGb: "", storageMediumId: "", storageType: "", driveLetter: "", fileSystemValueId: "", fileSystem: "", sourceReference: "", sourceAsOf: "", notes: "",
};
const emptyInstallation = {
  id: "", nodeStateId: "", productId: "", baselineOccurrenceId: "", installationRole: "application", instanceName: "", version: "", deploymentStatus: "installed", confidence: "assessed", sourceReference: "", sourceAsOf: "", notes: "",
};
const emptyConnection = {
  id: "", sourceNodeStateId: "", targetNodeStateId: "", connectionType: "network", label: "", status: "active", capacityMbps: "", sourceReference: "", sourceAsOf: "", notes: "",
};

type FieldChange = { label: string; before: string; after: string };
type ConfigurationDelta = { id: string; kind: "added" | "removed" | "modified"; subject: string; detail: string; changes: FieldChange[] };

function capacity(state: ReleaseInfrastructureNode) {
  const parts = [
    state.cpuCores == null ? "" : `${state.cpuCores} CPU`,
    state.memoryGb == null ? "" : `${state.memoryGb} GB RAM`,
    state.storageGb == null ? "" : `${state.storageGb} GB ${state.storageType || "storage"}`,
  ].filter(Boolean);
  if (state.driveLetter) parts.push(`${state.driveLetter}${state.fileSystem ? ` · ${state.fileSystem}` : ""}`);
  return parts.join(" · ") || "Capacity not recorded";
}

function stateParentNodeId(state: ReleaseInfrastructureNode | undefined, stateById: Map<string, ReleaseInfrastructureNode>) {
  if (!state?.parentStateId) return "";
  return stateById.get(state.parentStateId)?.infrastructureNodeId || "";
}

function configurationComparison(portfolio: InfrastructurePortfolio, platformId: string | undefined, beforeReleaseId: string, afterReleaseId: string) {
  if (!beforeReleaseId || !afterReleaseId || beforeReleaseId === afterReleaseId) return { nodeDeltas: [] as ConfigurationDelta[], installationDeltas: [] as ConfigurationDelta[], connectionDeltas: [] as ConfigurationDelta[] };
  const nodeById = new Map(portfolio.nodes.map((node) => [node.id, node]));
  const stateById = new Map(portfolio.states.map((state) => [state.id, state]));
  const inScope = (candidatePlatformId: string) => !platformId || candidatePlatformId === platformId;
  const beforeStates = portfolio.states.filter((state) => inScope(state.platformId) && state.releaseId === beforeReleaseId && state.lifecycleStatus !== "absent");
  const afterStates = portfolio.states.filter((state) => inScope(state.platformId) && state.releaseId === afterReleaseId && state.lifecycleStatus !== "absent");
  const beforeByNode = new Map(beforeStates.map((state) => [state.infrastructureNodeId, state]));
  const afterByNode = new Map(afterStates.map((state) => [state.infrastructureNodeId, state]));
  const nodeDeltas: ConfigurationDelta[] = [];
  for (const nodeId of new Set([...beforeByNode.keys(), ...afterByNode.keys()])) {
    const before = beforeByNode.get(nodeId);
    const after = afterByNode.get(nodeId);
    const node = nodeById.get(nodeId);
    const subject = node ? `${node.code} · ${node.name}` : nodeId;
    const detail = node ? nodeTypeLabels[node.nodeType] : "Infrastructure node";
    if (!before && after) { nodeDeltas.push({ id: `node-added-${nodeId}`, kind: "added", subject, detail, changes: [{ label: "Release presence", before: "Not present", after: "Present" }] }); continue; }
    if (before && !after) { nodeDeltas.push({ id: `node-removed-${nodeId}`, kind: "removed", subject, detail, changes: [{ label: "Release presence", before: "Present", after: "Not present" }] }); continue; }
    if (!before || !after) continue;
    const beforeParent = nodeById.get(stateParentNodeId(before, stateById));
    const afterParent = nodeById.get(stateParentNodeId(after, stateById));
    const candidates: Array<[string, unknown, unknown]> = [
      ["Parent placement", beforeParent ? `${beforeParent.code} · ${beforeParent.name}` : "Platform root", afterParent ? `${afterParent.code} · ${afterParent.name}` : "Platform root"],
      ["Lifecycle", readable(before.lifecycleStatus), readable(after.lifecycleStatus)],
      ["Operating state", readable(before.operatingState), readable(after.operatingState)],
      ["CPU cores", before.cpuCores, after.cpuCores],
      ["Memory (GB)", before.memoryGb, after.memoryGb],
      ["Storage (GB)", before.storageGb, after.storageGb],
      ["Storage medium", before.storageType, after.storageType],
      ["Drive / mount", before.driveLetter, after.driveLetter],
      ["File system", before.fileSystem, after.fileSystem],
    ];
    const changes = candidates.filter(([, previous, next]) => valueOrUnknown(previous) !== valueOrUnknown(next)).map(([label, previous, next]) => ({ label, before: valueOrUnknown(previous), after: valueOrUnknown(next) }));
    if (changes.length) nodeDeltas.push({ id: `node-modified-${nodeId}`, kind: "modified", subject, detail, changes });
  }

  const stateNode = (stateId: string) => stateById.get(stateId)?.infrastructureNodeId || "";
  const installKey = (item: InfrastructureProductInstallation) => [stateNode(item.nodeStateId), item.productId, item.installationRole, item.instanceName || ""].join("|");
  const beforeInstallations = portfolio.installations.filter((item) => inScope(item.platformId) && item.releaseId === beforeReleaseId && item.deploymentStatus !== "absent");
  const afterInstallations = portfolio.installations.filter((item) => inScope(item.platformId) && item.releaseId === afterReleaseId && item.deploymentStatus !== "absent");
  const beforeInstallByKey = new Map(beforeInstallations.map((item) => [installKey(item), item]));
  const afterInstallByKey = new Map(afterInstallations.map((item) => [installKey(item), item]));
  const installationDeltas: ConfigurationDelta[] = [];
  for (const key of new Set([...beforeInstallByKey.keys(), ...afterInstallByKey.keys()])) {
    const before = beforeInstallByKey.get(key);
    const after = afterInstallByKey.get(key);
    const item = after || before;
    if (!item) continue;
    const node = nodeById.get(stateNode(item.nodeStateId));
    const detail = `${readable(item.installationRole)} · ${node?.code || "Node not identified"}`;
    if (!before && after) { installationDeltas.push({ id: `installation-added-${key}`, kind: "added", subject: item.productName, detail, changes: [{ label: "Installation", before: "Not installed", after: `${after.version || "Version not recorded"} · ${readable(after.deploymentStatus)}` }] }); continue; }
    if (before && !after) { installationDeltas.push({ id: `installation-removed-${key}`, kind: "removed", subject: item.productName, detail, changes: [{ label: "Installation", before: `${before.version || "Version not recorded"} · ${readable(before.deploymentStatus)}`, after: "Not installed" }] }); continue; }
    if (!before || !after) continue;
    const changes = [["Version", before.version, after.version], ["Deployment status", readable(before.deploymentStatus), readable(after.deploymentStatus)]]
      .filter(([, previous, next]) => valueOrUnknown(previous) !== valueOrUnknown(next))
      .map(([label, previous, next]) => ({ label: String(label), before: valueOrUnknown(previous), after: valueOrUnknown(next) }));
    if (changes.length) installationDeltas.push({ id: `installation-modified-${key}`, kind: "modified", subject: item.productName, detail, changes });
  }

  const connectionKey = (item: InfrastructureConnection) => [stateNode(item.sourceNodeStateId), stateNode(item.targetNodeStateId), item.connectionType, item.label || ""].join("|");
  const beforeConnections = portfolio.connections.filter((item) => inScope(item.platformId) && item.releaseId === beforeReleaseId && item.status !== "retired");
  const afterConnections = portfolio.connections.filter((item) => inScope(item.platformId) && item.releaseId === afterReleaseId && item.status !== "retired");
  const beforeConnectionByKey = new Map(beforeConnections.map((item) => [connectionKey(item), item]));
  const afterConnectionByKey = new Map(afterConnections.map((item) => [connectionKey(item), item]));
  const connectionDeltas: ConfigurationDelta[] = [];
  for (const key of new Set([...beforeConnectionByKey.keys(), ...afterConnectionByKey.keys()])) {
    const before = beforeConnectionByKey.get(key);
    const after = afterConnectionByKey.get(key);
    const item = after || before;
    if (!item) continue;
    const source = nodeById.get(stateNode(item.sourceNodeStateId));
    const target = nodeById.get(stateNode(item.targetNodeStateId));
    const subject = `${source?.code || "Unknown"} → ${target?.code || "Unknown"}`;
    const detail = `${readable(item.connectionType)}${item.label ? ` · ${item.label}` : ""}`;
    if (!before && after) { connectionDeltas.push({ id: `connection-added-${key}`, kind: "added", subject, detail, changes: [{ label: "Connection", before: "Not present", after: "Present" }] }); continue; }
    if (before && !after) { connectionDeltas.push({ id: `connection-removed-${key}`, kind: "removed", subject, detail, changes: [{ label: "Connection", before: "Present", after: "Not present" }] }); continue; }
    if (!before || !after) continue;
    const changes = [["Status", readable(before.status), readable(after.status)], ["Capacity (Mbps)", before.capacityMbps, after.capacityMbps]]
      .filter(([, previous, next]) => valueOrUnknown(previous) !== valueOrUnknown(next))
      .map(([label, previous, next]) => ({ label: String(label), before: valueOrUnknown(previous), after: valueOrUnknown(next) }));
    if (changes.length) connectionDeltas.push({ id: `connection-modified-${key}`, kind: "modified", subject, detail, changes });
  }
  return { nodeDeltas, installationDeltas, connectionDeltas };
}

function ComparisonGroup({ title, deltas }: { title: string; deltas: ConfigurationDelta[] }) {
  if (!deltas.length) return null;
  return <section className="infra-comparison-group"><div className="section-toolbar"><h4>{title}</h4><span>{deltas.length} changes</span></div><div className="delta-list">{deltas.map((delta) => <article className="delta-card" key={delta.id}><div className="section-toolbar"><div><span className={`delta-kind delta-${delta.kind}`}>{delta.kind}</span><h3>{delta.subject}</h3></div><span className="entity-meta">{delta.detail}</span></div><div className="infra-field-deltas">{delta.changes.map((change) => <div key={change.label}><strong>{change.label}</strong><p className="delta-transition"><span className="infra-before">− {change.before}</span><b>→</b><span className="infra-after">+ {change.after}</span></p></div>)}</div></article>)}</div></section>;
}

export function InfrastructureComparison({ portfolio, beforeReleaseId, afterReleaseId, platformId }: { portfolio: InfrastructurePortfolio; beforeReleaseId: string; afterReleaseId: string; platformId?: string }) {
  const comparison = useMemo(() => configurationComparison(portfolio, platformId, beforeReleaseId, afterReleaseId), [portfolio, platformId, beforeReleaseId, afterReleaseId]);
  const total = comparison.nodeDeltas.length + comparison.installationDeltas.length + comparison.connectionDeltas.length;
  return <div className="infrastructure-comparison-results"><section className="delta-summary"><div><span>Total changes</span><strong>{total}</strong></div><div><span>Node changes</span><strong>{comparison.nodeDeltas.length}</strong></div><div><span>Product installation changes</span><strong>{comparison.installationDeltas.length}</strong></div><div><span>Connection changes</span><strong>{comparison.connectionDeltas.length}</strong></div></section>{!total ? <article className="domain-card empty-state"><h3>No configuration differences recorded</h3><p>The two Releases have the same governed nodes, Release state, Product installations, and connections{platformId ? " for this Platform" : ""}.</p></article> : <><ComparisonGroup title="Infrastructure nodes" deltas={comparison.nodeDeltas} /><ComparisonGroup title="Installed Products" deltas={comparison.installationDeltas} /><ComparisonGroup title="Connections" deltas={comparison.connectionDeltas} /></>}</div>;
}

function StateBranch({ state, nodes, states, installations, focusedStateIds, onEditState, onAddChild, onAddProduct }: { state: ReleaseInfrastructureNode; nodes: Map<string, InfrastructureNode>; states: ReleaseInfrastructureNode[]; installations: InfrastructureProductInstallation[]; focusedStateIds?: Set<string>; onEditState?: (state: ReleaseInfrastructureNode) => void; onAddChild?: (state: ReleaseInfrastructureNode) => void; onAddProduct?: (state: ReleaseInfrastructureNode) => void }) {
  const node = nodes.get(state.infrastructureNodeId);
  const children = states.filter((item) => item.parentStateId === state.id);
  const products = installations.filter((item) => item.nodeStateId === state.id && item.deploymentStatus !== "absent");
  if (!node) return null;
  const focused = focusedStateIds?.has(state.id) || false;
  return <li className={`infra-branch infra-type-${node.nodeType}${focused ? " infra-focused" : ""}`} data-infra-focus={focused ? "true" : undefined}><article className="infra-node-card"><div className="infra-node-heading"><span className="record-type">{nodeTypeLabels[node.nodeType]}</span><span className={`status-pill status-${state.operatingState === "operational" ? "pass" : state.operatingState === "degraded" ? "warning" : "neutral"}`}>{readable(state.operatingState)}</span></div><h4><Link href={`/platforms/${encodeURIComponent(state.platformId)}?release=${encodeURIComponent(state.releaseName)}&focus=${encodeURIComponent(`infrastructure_state:${state.id}`)}`}>{node.code} · {node.name}</Link></h4><p>{capacity(state)}</p><div className="infra-installations">{products.map((item) => <span className={`infra-product infra-role-${item.installationRole}`} key={item.id}><b>{readable(item.installationRole)}</b><Link href={`/products/${encodeURIComponent(item.productId)}`}>{item.productName}</Link>{item.version ? <small>v{item.version}</small> : null}{item.sourceKey ? <small>{item.sourceKey}</small> : null}</span>)}{!products.length ? <small>No Product installations recorded</small> : null}</div>{onEditState ? <div className="entity-actions"><button className="mini-action" onClick={() => onEditState(state)}>Edit capacity &amp; Release state</button><button className="mini-action" onClick={() => onAddChild?.(state)}>Add child node</button><button className="mini-action" onClick={() => onAddProduct?.(state)}>Install Product</button></div> : null}</article>{children.length ? <ul>{children.map((child) => <StateBranch key={child.id} state={child} nodes={nodes} states={states} installations={installations} focusedStateIds={focusedStateIds} onEditState={onEditState} onAddChild={onAddChild} onAddProduct={onAddProduct} />)}</ul> : null}</li>;
}

export function InfrastructureTree({ portfolio, releaseId, platformId, focus, emptyMessage = "No governed infrastructure configuration is recorded for this scope." }: { portfolio: InfrastructurePortfolio; releaseId: string; platformId?: string; focus?: string; emptyMessage?: string }) {
  const platformIds = useMemo(() => {
    if (!platformId) return null;
    const ids = new Set([platformId]); let changed = true;
    while (changed) { changed = false; for (const platform of portfolio.platforms) if (platform.parentId && ids.has(platform.parentId) && !ids.has(platform.id)) { ids.add(platform.id); changed = true; } }
    return ids;
  }, [platformId, portfolio.platforms]);
  const states = useMemo(() => portfolio.states.filter((item) => item.releaseId === releaseId && item.lifecycleStatus !== "absent" && (!platformIds || platformIds.has(item.platformId))), [platformIds, portfolio.states, releaseId]);
  const stateIds = useMemo(() => new Set(states.map((item) => item.id)), [states]);
  const nodes = useMemo(() => new Map(portfolio.nodes.map((item) => [item.id, item])), [portfolio.nodes]);
  const installations = useMemo(() => portfolio.installations.filter((item) => item.releaseId === releaseId && stateIds.has(item.nodeStateId)), [portfolio.installations, releaseId, stateIds]);
  const platforms = useMemo(() => portfolio.platforms.filter((item) => states.some((state) => state.platformId === item.id)), [portfolio.platforms, states]);
  const releaseName = portfolio.releases.find((item) => item.id === releaseId)?.name || releaseId;
  const focusedStateIds = useMemo(() => {
    const result = new Set<string>();
    const [kind, id] = (focus || "").split(":", 2);
    if (kind === "infrastructure_state" && stateIds.has(id)) result.add(id);
    if (kind === "infrastructure_node") for (const state of states) if (state.infrastructureNodeId === id) result.add(state.id);
    if (kind === "infrastructure_installation") { const installation = installations.find((item) => item.id === id); if (installation) result.add(installation.nodeStateId); }
    if (kind === "infrastructure_connection") { const connection = portfolio.connections.find((item) => item.id === id); if (connection) { result.add(connection.sourceNodeStateId); result.add(connection.targetNodeStateId); } }
    return result;
  }, [focus, installations, portfolio.connections, stateIds, states]);
  useEffect(() => { if (!focusedStateIds.size) return; const timer = window.setTimeout(() => document.querySelector('[data-infra-focus="true"]')?.scrollIntoView({ block: "center", behavior: "smooth" }), 50); return () => window.clearTimeout(timer); }, [focusedStateIds]);
  if (!states.length) return <article className="empty-state domain-card"><h3>Infrastructure not recorded</h3><p>{emptyMessage}</p></article>;
  return <div className="infra-platform-list">{platforms.map((platform) => {
    const scoped = states.filter((item) => item.platformId === platform.id);
    const scopedIds = new Set(scoped.map((item) => item.id));
    const roots = scoped.filter((item) => !item.parentStateId || !scopedIds.has(item.parentStateId));
    const connections = portfolio.connections.filter((item) => item.releaseId === releaseId && item.platformId === platform.id);
    return <section className="infra-platform" key={platform.id}><header><div><span className="eyebrow">{platform.platformType.toUpperCase()} PLATFORM</span><h3><Link href={`/platforms/${encodeURIComponent(platform.id)}?release=${encodeURIComponent(releaseName)}`}>{platform.code} · {platform.name}</Link></h3></div><span>{scoped.length} nodes · {installations.filter((item) => scopedIds.has(item.nodeStateId)).length} Product installations</span></header><ul className="infra-tree">{roots.map((root) => <StateBranch key={root.id} state={root} nodes={nodes} states={scoped} installations={installations} focusedStateIds={focusedStateIds} />)}</ul>{connections.length ? <div className="infra-connections"><strong>Connections</strong>{connections.map((connection) => <Link key={connection.id} href={`/platforms/${encodeURIComponent(platform.id)}?release=${encodeURIComponent(releaseName)}&focus=${encodeURIComponent(`infrastructure_connection:${connection.id}`)}`}>{readable(connection.connectionType)} · {nodes.get(states.find((item) => item.id === connection.sourceNodeStateId)?.infrastructureNodeId || "")?.code || "Unknown"} → {nodes.get(states.find((item) => item.id === connection.targetNodeStateId)?.infrastructureNodeId || "")?.code || "Unknown"}{connection.capacityMbps ? ` · ${connection.capacityMbps} Mbps` : ""}</Link>)}</div> : null}</section>;
  })}</div>;
}

export function InfrastructureWorkspace({ platformId, initialReleaseId, initialReleaseName, focus }: { platformId: string; initialReleaseId?: string; initialReleaseName?: string; focus?: string }) {
  const { extensions, loading, error, mutate } = useTopologyExtensions();
  const portfolio = extensions.infrastructure;
  const [releaseId, setReleaseId] = useState(initialReleaseId || "");
  const [comparisonReleaseId, setComparisonReleaseId] = useState("");
  const [mode, setMode] = useState<"node" | "node_identity" | "state" | "installation" | "connection" | "remove" | null>(null);
  const [nodeForm, setNodeForm] = useState(emptyNode);
  const [stateForm, setStateForm] = useState(emptyState);
  const [installationForm, setInstallationForm] = useState(emptyInstallation);
  const [connectionForm, setConnectionForm] = useState(emptyConnection);
  const [removeForm, setRemoveForm] = useState({ kind: "installation", id: "", rationale: "" });
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");
  const [productSearch, setProductSearch] = useState("");
  const latestConfiguredReleaseId = [...portfolio.releases].reverse().find((release) => portfolio.states.some((state) => state.platformId === platformId && state.releaseId === release.id))?.id;
  const releaseIdFromName = portfolio.releases.find((item) => item.name === initialReleaseName)?.id || "";
  const effectiveReleaseId = releaseId || initialReleaseId || releaseIdFromName || latestConfiguredReleaseId || portfolio.releases.at(-1)?.id || "";
  const configuredReleaseIds = portfolio.releases.filter((release) => portfolio.states.some((state) => state.platformId === platformId && state.releaseId === release.id)).map((release) => release.id);
  const currentConfiguredIndex = configuredReleaseIds.indexOf(effectiveReleaseId);
  const defaultComparisonReleaseId = currentConfiguredIndex > 0 ? configuredReleaseIds[currentConfiguredIndex - 1] : configuredReleaseIds.find((item) => item !== effectiveReleaseId) || "";
  const effectiveComparisonReleaseId = comparisonReleaseId && comparisonReleaseId !== effectiveReleaseId ? comparisonReleaseId : defaultComparisonReleaseId;
  const states = portfolio.states.filter((item) => item.platformId === platformId && item.releaseId === effectiveReleaseId);
  const installations = portfolio.installations.filter((item) => item.platformId === platformId && item.releaseId === effectiveReleaseId);
  const nodeById = new Map(portfolio.nodes.map((item) => [item.id, item]));
  const filteredProducts = portfolio.products.filter((item) => !productSearch || `${item.name} ${item.shortName || ""} ${item.productType || ""}`.toLowerCase().includes(productSearch.toLowerCase())).slice(0, 120);
  const occurrenceOptions = portfolio.occurrenceOptions.filter((item) => item.releaseId === effectiveReleaseId && (!installationForm.productId || !item.productId || item.productId === installationForm.productId));
  const storageMedia = portfolio.referenceValues.filter((item) => item.category === "storage_medium");
  const fileSystems = portfolio.referenceValues.filter((item) => item.category === "file_system");
  const releaseName = (id: string) => portfolio.releases.find((item) => item.id === id)?.name || "Release not identified";

  async function act(action: string, payload: Record<string, unknown>, message: string) { setSaving(true); setNotice(""); try { await mutate(action, payload); setMode(null); setNotice(message); } catch (reason) { setNotice(reason instanceof Error ? reason.message : "Infrastructure update failed."); } finally { setSaving(false); } }
  function addNode(parent?: ReleaseInfrastructureNode) { setNodeForm(emptyNode); setStateForm({ ...emptyState, parentStateId: parent?.id || "" }); setMode("node"); }
  function editNodeState(state: ReleaseInfrastructureNode) { setStateForm({ id: state.id, infrastructureNodeId: state.infrastructureNodeId, parentStateId: state.parentStateId || "", lifecycleStatus: state.lifecycleStatus, operatingState: state.operatingState, confidence: state.confidence, cpuCores: state.cpuCores?.toString() || "", memoryGb: state.memoryGb?.toString() || "", storageGb: state.storageGb?.toString() || "", storageMediumId: state.storageMediumId || "", storageType: state.storageType || "", driveLetter: state.driveLetter || "", fileSystemValueId: state.fileSystemValueId || "", fileSystem: state.fileSystem || "", sourceReference: state.sourceReference || "", sourceAsOf: state.sourceAsOf || "", notes: state.notes || "" }); setMode("state"); }
  function addInstallation(state: ReleaseInfrastructureNode) { setInstallationForm({ ...emptyInstallation, nodeStateId: state.id }); setProductSearch(""); setMode("installation"); }
  function editNodeIdentity(node: InfrastructureNode) { setNodeForm({ id: node.id, nodeType: node.nodeType, code: node.code, name: node.name, manufacturerOrganizationId: node.manufacturerOrganizationId || "", hardwareProductId: node.hardwareProductId || "", assetTag: node.assetTag || "", serialNumber: node.serialNumber || "", lifecycleStatus: node.lifecycleStatus, description: node.description || "" }); setMode("node_identity"); }
  async function saveNewNode() { setSaving(true); setNotice(""); try { const nodeResult = await mutate("save_infrastructure_node", { ...nodeForm, platformId }); const infrastructureNodeId = nodeResult.id || ""; await mutate("save_release_infrastructure_node", { ...stateForm, infrastructureNodeId, releaseId: effectiveReleaseId }); setMode(null); setNotice("Infrastructure node added to the Release configuration."); } catch (reason) { setNotice(reason instanceof Error ? reason.message : "Infrastructure update failed."); } finally { setSaving(false); } }
  function editInstallation(item: InfrastructureProductInstallation) { setInstallationForm({ id: item.id, nodeStateId: item.nodeStateId, productId: item.productId, baselineOccurrenceId: item.baselineOccurrenceId || "", installationRole: item.installationRole, instanceName: item.instanceName || "", version: item.version || "", deploymentStatus: item.deploymentStatus, confidence: item.confidence, sourceReference: item.sourceReference || "", sourceAsOf: item.sourceAsOf || "", notes: item.notes || "" }); setProductSearch(item.productName); setMode("installation"); }
  function chooseStorageMedium(id: string) { const value = storageMedia.find((item) => item.id === id); setStateForm({ ...stateForm, storageMediumId: id, storageType: value?.code || "" }); }
  function chooseFileSystem(id: string) { const value = fileSystems.find((item) => item.id === id); setStateForm({ ...stateForm, fileSystemValueId: id, fileSystem: value?.code || "" }); }

  if (loading) return <p className="empty">Loading governed infrastructure…</p>;
  if (error) return <p className="error-copy">{error}</p>;
  return <>
    <div className="section-toolbar"><div><span className="eyebrow">RELEASE CONFIGURATION</span><h3>Infrastructure and installed Products</h3></div><div className="toolbar-actions"><label className="compare-select">Release<select value={effectiveReleaseId} onChange={(event) => { setReleaseId(event.target.value); setComparisonReleaseId(""); }}>{portfolio.releases.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><button className="primary-button" disabled={!effectiveReleaseId} onClick={() => addNode()}>Add infrastructure node / VM</button></div></div>
    <p className="entity-meta">Hardware and VM identities are stable. Parent placement, capacity, OS, hypervisor, applications, and connections are recorded for the selected Release. Blank fields remain unknown.</p>
    <aside className="contract-strip"><strong>Where to edit</strong><span>The tree is a configuration map. In the <b>Release node register</b> below, use <b>Edit identity</b> for a stable code, name, type, or serial number; use <b>Edit capacity &amp; Release state</b> for CPU cores, memory, storage, placement, lifecycle, and source evidence. To record a VM, choose <b>Add infrastructure node / VM</b>, select <b>Virtual machine</b>, and choose its host as the parent.</span></aside>
    <InfrastructureTree portfolio={portfolio} releaseId={effectiveReleaseId} platformId={platformId} focus={focus} />
    {states.length ? <section className="domain-card infra-register"><div className="section-toolbar"><h3>Release node register</h3><span>{states.length} nodes</span></div><div className="domain-table-wrap"><table><thead><tr><th>Node</th><th>Type / confidence</th><th>Parent</th><th>Capacity</th><th>Products</th><th>Actions</th></tr></thead><tbody>{states.map((state) => { const node = nodeById.get(state.infrastructureNodeId); const parent = nodeById.get(states.find((item) => item.id === state.parentStateId)?.infrastructureNodeId || ""); return <tr key={state.id}><td><strong>{node?.code}</strong><small>{node?.name}</small></td><td>{node ? nodeTypeLabels[node.nodeType] : "Unknown"}<small>{readable(state.confidence)}</small></td><td>{parent?.code || "Platform root"}</td><td>{capacity(state)}</td><td>{installations.filter((item) => item.nodeStateId === state.id).map((item) => <button className="tag-button" key={item.id} onClick={() => editInstallation(item)}>{item.productName}<small>{readable(item.confidence)}</small></button>)}</td><td><div className="entity-actions">{node ? <button className="mini-action" onClick={() => editNodeIdentity(node)}>Edit identity</button> : null}<button className="mini-action" onClick={() => editNodeState(state)}>Edit capacity &amp; Release state</button><button className="mini-action" onClick={() => addInstallation(state)}>Install Product</button><button className="mini-action" onClick={() => addNode(state)}>Add child</button><CallNoteControl compact context={{ kind: "infrastructure_state", id: state.id, label: `${node?.code || "Infrastructure node"} · ${releaseName(state.releaseId)}` }} /></div></td></tr>; })}</tbody></table></div></section> : null}
    {states.length > 1 ? <section className="domain-card"><div className="section-toolbar"><div><span className="eyebrow">RELEASE LINKS</span><h3>Network, power, storage, cluster, and management connections</h3></div><button className="ghost-button" onClick={() => { setConnectionForm(emptyConnection); setMode("connection"); }}>Add connection</button></div><div className="chip-list">{portfolio.connections.filter((item) => item.releaseId === effectiveReleaseId && item.platformId === platformId).map((item) => <button className="domain-chip" key={item.id} onClick={() => { setConnectionForm({ id: item.id, sourceNodeStateId: item.sourceNodeStateId, targetNodeStateId: item.targetNodeStateId, connectionType: item.connectionType, label: item.label || "", status: item.status, capacityMbps: item.capacityMbps?.toString() || "", sourceReference: item.sourceReference || "", sourceAsOf: item.sourceAsOf || "", notes: item.notes || "" }); setMode("connection"); }}><strong>{readable(item.connectionType)}</strong><span>{item.label || "Recorded connection"}</span></button>)}</div></section> : null}
    {configuredReleaseIds.length > 1 ? <section className="domain-section infra-comparison"><div className="section-toolbar"><div><span className="eyebrow">RELEASE-TO-RELEASE CONFIGURATION DELTA</span><h3>Infrastructure changes by stable identity</h3></div><label className="compare-select">Compare <select value={effectiveComparisonReleaseId} onChange={(event) => setComparisonReleaseId(event.target.value)}>{configuredReleaseIds.filter((item) => item !== effectiveReleaseId).map((item) => <option key={item} value={item}>{releaseName(item)}</option>)}</select> → <strong>{releaseName(effectiveReleaseId)}</strong></label></div><p className="entity-meta">The comparison matches the same governed node across Releases. Release-row identifiers are not used as identity. Product installations and connections are compared separately.</p><InfrastructureComparison portfolio={portfolio} platformId={platformId} beforeReleaseId={effectiveComparisonReleaseId} afterReleaseId={effectiveReleaseId} /></section> : null}
    {mode === "node" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-node-title" className="wide-modal"><span className="eyebrow">CANONICAL INFRASTRUCTURE</span><h2 id="infra-node-title">Add node and Release state</h2><p>Create the stable identity once. This dialog also places it in {releaseName(effectiveReleaseId)}.</p><div className="form-grid"><label className="modal-field">Type<select value={nodeForm.nodeType} onChange={(event) => setNodeForm({ ...nodeForm, nodeType: event.target.value as InfrastructureNodeType })}>{Object.entries(nodeTypeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label className="modal-field">Code<input value={nodeForm.code} onChange={(event) => setNodeForm({ ...nodeForm, code: event.target.value })} /></label><label className="modal-field">Name<input value={nodeForm.name} onChange={(event) => setNodeForm({ ...nodeForm, name: event.target.value })} /></label><label className="modal-field">Parent in this Release<select value={stateForm.parentStateId} onChange={(event) => setStateForm({ ...stateForm, parentStateId: event.target.value })}><option value="">Platform root</option>{states.map((item) => <option key={item.id} value={item.id}>{nodeById.get(item.infrastructureNodeId)?.code} · {nodeById.get(item.infrastructureNodeId)?.name}</option>)}</select></label><label className="modal-field">Manufacturer<select value={nodeForm.manufacturerOrganizationId} onChange={(event) => setNodeForm({ ...nodeForm, manufacturerOrganizationId: event.target.value })}><option value="">Not recorded</option>{portfolio.organizations.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="modal-field">Hardware Product<select value={nodeForm.hardwareProductId} onChange={(event) => setNodeForm({ ...nodeForm, hardwareProductId: event.target.value })}><option value="">Not cataloged</option>{portfolio.products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="modal-field">Asset tag<input value={nodeForm.assetTag} onChange={(event) => setNodeForm({ ...nodeForm, assetTag: event.target.value })} /></label><label className="modal-field">Serial number<input value={nodeForm.serialNumber} onChange={(event) => setNodeForm({ ...nodeForm, serialNumber: event.target.value })} /></label><label className="modal-field">CPU cores<input type="number" min="0" step="0.1" value={stateForm.cpuCores} onChange={(event) => setStateForm({ ...stateForm, cpuCores: event.target.value })} /></label><label className="modal-field">Memory (GB)<input type="number" min="0" step="0.1" value={stateForm.memoryGb} onChange={(event) => setStateForm({ ...stateForm, memoryGb: event.target.value })} /></label><label className="modal-field">Storage (GB)<input type="number" min="0" step="0.1" value={stateForm.storageGb} onChange={(event) => setStateForm({ ...stateForm, storageGb: event.target.value })} /></label><label className="modal-field">Storage medium<select value={stateForm.storageMediumId} onChange={(event) => chooseStorageMedium(event.target.value)}><option value="">Not recorded</option>{storageMedia.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label></div><label className="modal-field">Description<textarea rows={3} value={nodeForm.description} onChange={(event) => setNodeForm({ ...nodeForm, description: event.target.value })} /></label><footer><button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="primary-button" disabled={saving || !nodeForm.code || !nodeForm.name} onClick={() => void saveNewNode()}>{saving ? "Saving…" : "Create node"}</button></footer></ViewportModal> : null}
    {mode === "state" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-state-title"><div className="section-toolbar"><div><span className="eyebrow">RELEASE NODE STATE</span><h2 id="infra-state-title">{nodeById.get(stateForm.infrastructureNodeId)?.code} · {releaseName(effectiveReleaseId)}</h2></div>{stateForm.id ? <CallNoteControl compact context={{ kind: "infrastructure_state", id: stateForm.id, label: `${nodeById.get(stateForm.infrastructureNodeId)?.code || "Infrastructure node"} · ${releaseName(effectiveReleaseId)}` }} /> : null}</div><div className="form-grid"><label className="modal-field">Parent<select value={stateForm.parentStateId} onChange={(event) => setStateForm({ ...stateForm, parentStateId: event.target.value })}><option value="">Platform root</option>{states.filter((item) => item.id !== stateForm.id).map((item) => <option key={item.id} value={item.id}>{nodeById.get(item.infrastructureNodeId)?.code} · {nodeById.get(item.infrastructureNodeId)?.name}</option>)}</select></label><label className="modal-field">Lifecycle<select value={stateForm.lifecycleStatus} onChange={(event) => setStateForm({ ...stateForm, lifecycleStatus: event.target.value })}>{["planned", "active", "retired", "absent"].map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Operating state<select value={stateForm.operatingState} onChange={(event) => setStateForm({ ...stateForm, operatingState: event.target.value })}>{["unknown", "operational", "degraded", "offline", "not_installed"].map((item) => <option value={item} key={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Evidence confidence<select value={stateForm.confidence} onChange={(event) => setStateForm({ ...stateForm, confidence: event.target.value })}>{["reported", "assessed", "confirmed"].map((item) => <option value={item} key={item}>{readable(item)}</option>)}</select></label><label className="modal-field">CPU cores<input type="number" min="0" step="0.1" value={stateForm.cpuCores} onChange={(event) => setStateForm({ ...stateForm, cpuCores: event.target.value })} /></label><label className="modal-field">Memory (GB)<input type="number" min="0" step="0.1" value={stateForm.memoryGb} onChange={(event) => setStateForm({ ...stateForm, memoryGb: event.target.value })} /></label><label className="modal-field">Storage (GB)<input type="number" min="0" step="0.1" value={stateForm.storageGb} onChange={(event) => setStateForm({ ...stateForm, storageGb: event.target.value })} /></label><label className="modal-field">Storage medium<select value={stateForm.storageMediumId} onChange={(event) => chooseStorageMedium(event.target.value)}><option value="">Not recorded</option>{storageMedia.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label className="modal-field">Drive / mount<input value={stateForm.driveLetter} onChange={(event) => setStateForm({ ...stateForm, driveLetter: event.target.value })} /></label><label className="modal-field">File system<select value={stateForm.fileSystemValueId} onChange={(event) => chooseFileSystem(event.target.value)}><option value="">Not recorded</option>{fileSystems.map((item) => <option key={item.id} value={item.id}>{item.code} · {item.name}</option>)}</select></label><label className="modal-field">Source as of<input type="date" value={stateForm.sourceAsOf} onChange={(event) => setStateForm({ ...stateForm, sourceAsOf: event.target.value })} /></label></div>{(stateForm.storageType && !stateForm.storageMediumId) || (stateForm.fileSystem && !stateForm.fileSystemValueId) ? <p className="error-copy">This state contains an older free-text classification. Choose the governed storage medium or file system before saving.</p> : null}<label className="modal-field">Supporting reference<input value={stateForm.sourceReference} onChange={(event) => setStateForm({ ...stateForm, sourceReference: event.target.value })} /></label><label className="modal-field">Notes<textarea rows={3} value={stateForm.notes} onChange={(event) => setStateForm({ ...stateForm, notes: event.target.value })} /></label><footer><button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="primary-button" disabled={saving || Boolean(stateForm.storageType && !stateForm.storageMediumId) || Boolean(stateForm.fileSystem && !stateForm.fileSystemValueId)} onClick={() => void act("save_release_infrastructure_node", { ...stateForm, releaseId: effectiveReleaseId }, "Release infrastructure state saved.")}>Save state</button></footer></ViewportModal> : null}
    {mode === "installation" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-install-title" className="wide-modal"><div className="section-toolbar"><div><span className="eyebrow">GOVERNED PRODUCT PLACEMENT</span><h2 id="infra-install-title">Install Product on {nodeById.get(states.find((item) => item.id === installationForm.nodeStateId)?.infrastructureNodeId || "")?.code}</h2></div>{installationForm.id ? <CallNoteControl compact context={{ kind: "infrastructure_installation", id: installationForm.id, label: `${portfolio.products.find((item) => item.id === installationForm.productId)?.name || "Product"} installation` }} /> : null}</div><p>Operating systems, hypervisors, applications, and supporting software are canonical Products. The version belongs to this Release installation.</p><div className="form-grid"><label className="modal-field">Find Product<input value={productSearch} onChange={(event) => setProductSearch(event.target.value)} placeholder="Search name, short name, or type" /></label><label className="modal-field">Product<select value={installationForm.productId} onChange={(event) => setInstallationForm({ ...installationForm, productId: event.target.value, baselineOccurrenceId: "" })}><option value="">Choose governed Product</option>{filteredProducts.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.productType || "type not classified"}</option>)}</select></label><label className="modal-field">Installation role<select value={installationForm.installationRole} onChange={(event) => setInstallationForm({ ...installationForm, installationRole: event.target.value })}>{roles.map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Version<input value={installationForm.version} onChange={(event) => setInstallationForm({ ...installationForm, version: event.target.value })} /></label><label className="modal-field">Instance name<input value={installationForm.instanceName} onChange={(event) => setInstallationForm({ ...installationForm, instanceName: event.target.value })} placeholder="Only when multiple instances exist" /></label><label className="modal-field">Status<select value={installationForm.deploymentStatus} onChange={(event) => setInstallationForm({ ...installationForm, deploymentStatus: event.target.value })}>{["planned", "installed", "retired", "absent"].map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Evidence confidence<select value={installationForm.confidence} onChange={(event) => setInstallationForm({ ...installationForm, confidence: event.target.value })}>{["reported", "assessed", "confirmed"].map((item) => <option value={item} key={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Linked baseline record<select value={installationForm.baselineOccurrenceId} onChange={(event) => setInstallationForm({ ...installationForm, baselineOccurrenceId: event.target.value })}><option value="">No imported row link</option>{occurrenceOptions.map((item) => <option key={item.id} value={item.id}>{item.sourceKey} · {item.productName}</option>)}</select></label><label className="modal-field">Source as of<input type="date" value={installationForm.sourceAsOf} onChange={(event) => setInstallationForm({ ...installationForm, sourceAsOf: event.target.value })} /></label></div><label className="modal-field">Supporting reference<input value={installationForm.sourceReference} onChange={(event) => setInstallationForm({ ...installationForm, sourceReference: event.target.value })} /></label><label className="modal-field">Notes<textarea rows={3} value={installationForm.notes} onChange={(event) => setInstallationForm({ ...installationForm, notes: event.target.value })} /></label><footer>{installationForm.id ? <button className="danger-button" onClick={() => { setRemoveForm({ kind: "installation", id: installationForm.id, rationale: "" }); setMode("remove"); }}>Remove installation</button> : null}<button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="primary-button" disabled={saving || !installationForm.productId} onClick={() => void act("save_infrastructure_installation", installationForm, "Product installation saved.")}>Save installation</button></footer></ViewportModal> : null}
    {mode === "connection" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-connection-title"><div className="section-toolbar"><div><span className="eyebrow">RELEASE CONNECTION</span><h2 id="infra-connection-title">Record connection</h2></div>{connectionForm.id ? <CallNoteControl compact context={{ kind: "infrastructure_connection", id: connectionForm.id, label: connectionForm.label || `${readable(connectionForm.connectionType)} connection` }} /> : null}</div><div className="form-grid"><label className="modal-field">From<select value={connectionForm.sourceNodeStateId} onChange={(event) => setConnectionForm({ ...connectionForm, sourceNodeStateId: event.target.value })}><option value="">Choose node</option>{states.map((item) => <option key={item.id} value={item.id}>{nodeById.get(item.infrastructureNodeId)?.code}</option>)}</select></label><label className="modal-field">To<select value={connectionForm.targetNodeStateId} onChange={(event) => setConnectionForm({ ...connectionForm, targetNodeStateId: event.target.value })}><option value="">Choose node</option>{states.filter((item) => item.id !== connectionForm.sourceNodeStateId).map((item) => <option key={item.id} value={item.id}>{nodeById.get(item.infrastructureNodeId)?.code}</option>)}</select></label><label className="modal-field">Type<select value={connectionForm.connectionType} onChange={(event) => setConnectionForm({ ...connectionForm, connectionType: event.target.value })}>{["network", "power", "storage", "cluster", "management", "other"].map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Label<input value={connectionForm.label} onChange={(event) => setConnectionForm({ ...connectionForm, label: event.target.value })} /></label><label className="modal-field">Capacity (Mbps)<input type="number" min="0" value={connectionForm.capacityMbps} onChange={(event) => setConnectionForm({ ...connectionForm, capacityMbps: event.target.value })} /></label><label className="modal-field">Status<select value={connectionForm.status} onChange={(event) => setConnectionForm({ ...connectionForm, status: event.target.value })}>{["planned", "active", "retired"].map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label></div><label className="modal-field">Supporting reference<input value={connectionForm.sourceReference} onChange={(event) => setConnectionForm({ ...connectionForm, sourceReference: event.target.value })} /></label><label className="modal-field">Notes<textarea rows={3} value={connectionForm.notes} onChange={(event) => setConnectionForm({ ...connectionForm, notes: event.target.value })} /></label><footer>{connectionForm.id ? <button className="danger-button" onClick={() => { setRemoveForm({ kind: "connection", id: connectionForm.id, rationale: "" }); setMode("remove"); }}>Remove connection</button> : null}<button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="primary-button" disabled={saving || !connectionForm.sourceNodeStateId || !connectionForm.targetNodeStateId} onClick={() => void act("save_infrastructure_connection", connectionForm, "Infrastructure connection saved.")}>Save connection</button></footer></ViewportModal> : null}
    {mode === "remove" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-remove-title"><span className="eyebrow">AUDITED REMOVAL</span><h2 id="infra-remove-title">Remove {removeForm.kind}</h2><p>The Release history and audit event remain. State why this relationship is being removed.</p><label className="modal-field">Removal rationale<textarea rows={4} value={removeForm.rationale} onChange={(event) => setRemoveForm({ ...removeForm, rationale: event.target.value })} /></label><footer><button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="danger-button" disabled={saving || !removeForm.rationale.trim()} onClick={() => void act(removeForm.kind === "connection" ? "remove_infrastructure_connection" : "remove_infrastructure_installation", { id: removeForm.id, rationale: removeForm.rationale }, `${readable(removeForm.kind)} removed and audited.`)}>Confirm removal</button></footer></ViewportModal> : null}
    {mode === "node_identity" ? <ViewportModal onDismiss={() => setMode(null)} dismissDisabled={saving} labelledBy="infra-node-identity-title" className="wide-modal"><div className="section-toolbar"><div><span className="eyebrow">CANONICAL INFRASTRUCTURE</span><h2 id="infra-node-identity-title">Edit node identity</h2></div>{nodeForm.id ? <CallNoteControl compact context={{ kind: "infrastructure_node", id: nodeForm.id, label: `${nodeForm.code} · ${nodeForm.name}` }} /> : null}</div><p>These values describe the stable asset. Release-specific placement and capacity are edited separately.</p><div className="form-grid"><label className="modal-field">Type<select value={nodeForm.nodeType} onChange={(event) => setNodeForm({ ...nodeForm, nodeType: event.target.value as InfrastructureNodeType })}>{Object.entries(nodeTypeLabels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label><label className="modal-field">Code<input value={nodeForm.code} onChange={(event) => setNodeForm({ ...nodeForm, code: event.target.value })} /></label><label className="modal-field">Name<input value={nodeForm.name} onChange={(event) => setNodeForm({ ...nodeForm, name: event.target.value })} /></label><label className="modal-field">Lifecycle<select value={nodeForm.lifecycleStatus} onChange={(event) => setNodeForm({ ...nodeForm, lifecycleStatus: event.target.value })}>{["planned", "active", "retired"].map((item) => <option key={item} value={item}>{readable(item)}</option>)}</select></label><label className="modal-field">Manufacturer<select value={nodeForm.manufacturerOrganizationId} onChange={(event) => setNodeForm({ ...nodeForm, manufacturerOrganizationId: event.target.value })}><option value="">Not recorded</option>{portfolio.organizations.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="modal-field">Hardware Product<select value={nodeForm.hardwareProductId} onChange={(event) => setNodeForm({ ...nodeForm, hardwareProductId: event.target.value })}><option value="">Not cataloged</option>{portfolio.products.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="modal-field">Asset tag<input value={nodeForm.assetTag} onChange={(event) => setNodeForm({ ...nodeForm, assetTag: event.target.value })} /></label><label className="modal-field">Serial number<input value={nodeForm.serialNumber} onChange={(event) => setNodeForm({ ...nodeForm, serialNumber: event.target.value })} /></label></div><label className="modal-field">Description<textarea rows={3} value={nodeForm.description} onChange={(event) => setNodeForm({ ...nodeForm, description: event.target.value })} /></label><footer><button className="ghost-button" onClick={() => setMode(null)}>Cancel</button><button className="primary-button" disabled={saving || !nodeForm.code || !nodeForm.name} onClick={() => void act("save_infrastructure_node", { ...nodeForm, platformId }, "Infrastructure identity saved.")}>Save identity</button></footer></ViewportModal> : null}
    {notice ? <p className={notice.toLowerCase().includes("failed") || notice.toLowerCase().includes("choose") ? "error-copy" : "toast"}>{notice}</p> : null}
  </>;
}
